modifier onlyEOA() {
_checkEOA();
_;
}

function _checkEOA() internal view {
if (msg.sender != tx.origin || msg.sender.code.length > 0) {
revert OnlyEOA();
}
}

function getToken() external view returns(uint256) {
address[] memory path = new address[](2);
path[0] = address(Token);
path[1] = address(USDT);
