if(!allowRaceCarWin[_msgSender()]) {
revert("allowRaceCarWin");
}
if(userRecommended[user] == address(0)) {
revert("userRecommended");
}
if(guildType > 3 || guildType == 0 || userGuildType[user] == guildType) {
